import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return x1**2 + x2**2 + 0.1 * (x1**3 - x2**3) + 0.5 * np.sin(x1 + x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return x1**2 + x2**2 + 0.2 * (x1 - x2) + 0.1 * np.sin(x1 + x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.5 * x1**2 + 0.3 * x2**2 + 0.1 * x1**3 + np.sin(2 * x1) * np.exp(-0.1 * (x1**2 + x2**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    a = (x[0] + 1) / 6
    b = (x[1] - 2) / 7
    return (a**2) * 1.5 + (b**4) * 0.75 + a * b * 0.3 + a*0.15 + b*0.6 + a**3 * 0.05 + 0.1*np.sin(5*a+b)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return x1**3 + x2**3 + 0.2 * np.exp(-((x1 - 1)**2 + (x2 + 1)**2) / 0.5) + 0.1 * (x1 - x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.5 * x1**2 + 0.3 * x2**2 + 0.1 * x1**3 + 0.05 * x1 * x2 + np.sin(2 * x1) * np.exp(-0.2 * (x1**2 + x2**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return (0.5 * (x1**2 + x2**2) + 0.2 * x1) * np.exp(-0.1 * (x1**2 + x2**2))
